import{_ as t,o,c as d,a2 as a}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"MenuItem","description":"","frontmatter":{},"headers":[],"relativePath":"components/menu-item.md","filePath":"components/menu-item.md"}'),n={name:"components/menu-item.md"};function r(c,e,i,s,h,m){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="menuitem" tabindex="-1">MenuItem <a class="header-anchor" href="#menuitem" aria-label="Permalink to &quot;MenuItem&quot;">​</a></h1><p>MenuItem is one action of a menu.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for each action of a <a href="./menu">Menu</a> or of a <a href="./dropdown">Dropdown</a> with <code>menu</code>. A destructive action is <code>danger</code>, comes last after a <a href="./menu-divider">MenuDivider</a>, and its name ends with an ellipsis when a confirmation follows. Items that choose one value show the column of check marks with <code>checked</code>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>icon</code></td><td></td><td>An icon on the left (a name or a component)</td></tr><tr><td><code>checked</code></td><td></td><td>The column of check marks; a mark when true</td></tr><tr><td><code>kbd</code></td><td></td><td>A key hint at the right end</td></tr><tr><td><code>sub</code></td><td><code>false</code></td><td>The item opens a submenu: a chevron at the right end</td></tr><tr><td><code>on</code></td><td><code>false</code></td><td>Its submenu is open: it keeps the hover surface</td></tr><tr><td><code>danger</code></td><td><code>false</code></td><td>A destructive action: red text</td></tr><tr><td><code>disabled</code></td><td><code>false</code></td><td>Shown but not chosen: dimmed, no hover</td></tr><tr><td><code>href</code></td><td></td><td>Renders a link</td></tr><tr><td><code>onclick</code></td><td></td><td>Called when chosen</td></tr><tr><td><code>children</code></td><td>required</td><td>The name, or a Stack of two lines</td></tr></tbody></table><p>Other attributes (<code>data-*</code>, <code>aria-*</code>, <code>onmouseenter</code>) go to the element.</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>It is a <code>&lt;button&gt;</code> (an <code>&lt;a&gt;</code> with <code>href</code>) with <code>role=&quot;menuitem&quot;</code> and <code>tabindex=&quot;-1&quot;</code>; the menu moves the focus. It is at least as high as a list item, with pad-md at the sides and gap-sm between the icon or the check mark, the name and the key hint. The name is one line, trimmed to its ink, with an ellipsis. A control or a Stack inside is pad-md from the top and bottom edges, so the item grows with it. Hover shows the raise surface up to the edges of the menu; the focus ring is drawn inside.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/menu-item/" title="MenuItem" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/menu-item/" target="_blank" rel="noopener">MenuItem</a></figcaption></figure>',11)])])}const p=t(n,[["render",r]]);export{u as __pageData,p as default};
